/** Real local Jellyfin fixture, native remote controls and isolated provider switching. Emulator only. */
public final class AndroidJellyfinTest extends Instrumentation {
    private final List<Activity> opened=new ArrayList<>();
    private void check(boolean ok,String why){if(!ok)throw new AssertionError(why);}
    private Object field(Object target,String name)throws Exception{Field f=target.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(target);}
    private void ui(Runnable job){runOnMainSync(job);waitForIdleSync();}
    private interface Ready {boolean ready()throws Exception;}
    private void await(Ready ready,String why)throws Exception{long end=SystemClock.uptimeMillis()+30_000;while(SystemClock.uptimeMillis()<end){boolean[] value={false};ui(()->{try{value[0]=ready.ready();}catch(Exception e){throw new RuntimeException(e);}});if(value[0])return;Thread.sleep(100);}throw new AssertionError(why);}
    private <T extends Activity>T open(Class<T> type)throws Exception{T a=(T)startActivitySync(new Intent(getTargetContext(),type).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));opened.add(a);await(()->a.hasWindowFocus(),"No window focus");return a;}
    private List<View> controls(Activity a)throws Exception{return (List<View>)field(a,"controls");}
    private void press(View view){ui(()->view.requestFocus());sendKeyDownUpSync(KeyEvent.KEYCODE_DPAD_CENTER);waitForIdleSync();}
    private void setText(EditText view,String text){ui(()->view.setText(text));}
    private void capture(String name)throws Exception{Thread.sleep(500);Bitmap image=getUiAutomation().takeScreenshot();check(image!=null,"No screenshot");try(OutputStream out=new FileOutputStream(new File(getTargetContext().getExternalFilesDir(null),"jellyfin-"+name+".webp"))){image.compress(Bitmap.CompressFormat.WEBP_LOSSY,96,out);}finally{image.recycle();}}
    private void restore(SharedPreferences p,Map<String,?> before){SharedPreferences.Editor e=p.edit().clear();for(Map.Entry<String,?> item:before.entrySet()){Object v=item.getValue();if(v instanceof String)e.putString(item.getKey(),(String)v);else if(v instanceof Boolean)e.putBoolean(item.getKey(),(Boolean)v);else if(v instanceof Long)e.putLong(item.getKey(),(Long)v);else if(v instanceof Integer)e.putInt(item.getKey(),(Integer)v);else if(v instanceof Float)e.putFloat(item.getKey(),(Float)v);else if(v instanceof Set)e.putStringSet(item.getKey(),new HashSet<>((Set<String>)v));}e.commit();}
    private void authorize(JSONObject fixture,String code)throws Exception{
        URL url=new URL(fixture.getString("base")+"/QuickConnect/Authorize?code="+URLEncoder.encode(code,"UTF-8")+"&userId="+fixture.getString("userId"));HttpURLConnection c=(HttpURLConnection)url.openConnection();c.setRequestMethod("POST");c.setConnectTimeout(5000);c.setReadTimeout(5000);c.setRequestProperty("Authorization","MediaBrowser Client=\"VelaTest\", Device=\"Local fixture\", DeviceId=\"vela-fixture-test\", Version=\"1.0\", Token=\""+fixture.getString("token")+"\"");try{check(c.getResponseCode()==200,"Fixture could not authorize Quick Connect");}finally{c.disconnect();}
    }
    public void onCreate(Bundle args){super.onCreate(args);start();}
    public void onStart(){
        Context c=getTargetContext();Bundle result=new Bundle();Map<SharedPreferences,Map<String,?>> saved=new LinkedHashMap<>();File fixtureFile=new File(c.getExternalFilesDir(null),"jellyfin-fixture.json");
        try{
            check(Build.MODEL.contains("sdk")||Build.FINGERPRINT.contains("generic"),"Emulator required");check(!new PlexClient(c).connected()&&!new JellyfinClient(c).connected(),"Fixture requires unlinked personal libraries");Locale.setDefault(new Locale("es","ES"));
            for(SharedPreferences p:new SharedPreferences[]{new PlexClient(c).prefs,JellyfinClient.prefs(c),c.getSharedPreferences("library",0),Visuals.prefs(c),Personalization.prefs(c),SidebarApps.prefs(c),Updates.prefs(c),AmbientPrefs.get(c)})saved.put(p,new HashMap<>(p.getAll()));
            String raw;try(InputStream in=new FileInputStream(fixtureFile);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[2048];int n;while((n=in.read(b))!=-1){check(out.size()+n<16384,"Fixture too large");out.write(b,0,n);}raw=out.toString("UTF-8");}JSONObject fixture=new JSONObject(raw);check(fixture.getString("base").matches("http://127\\.0\\.0\\.1:[0-9]+"),"Only an owned loopback fixture is allowed");
            Updates.prefs(c).edit().putBoolean("automatic",false).commit();Personalization.prepare(c);Personalization.complete(c);JellyfinClient client=new JellyfinClient(c);Map<String,?> plexBefore=new HashMap<>(new PlexClient(c).prefs.getAll());int cache=Visuals.cacheKb(c);String[] apps=SidebarApps.slots(c);
            JellyfinLinkActivity link=open(JellyfinLinkActivity.class);setText((EditText)field(link,"address"),fixture.getString("base"));press(controls(link).get(1));await(()->(Integer)field(link,"page")==1&&!((TextView)field(link,"code")).getText().toString().isEmpty(),"Quick Connect code missing");authorize(fixture,((TextView)field(link,"code")).getText().toString());await(()->client.connected()&&(Integer)field(link,"page")==3,"Authorized code did not create a linked session");
            check(new LibraryClient(c).isJellyfin()&&client.prefs.getString("userId","").equals(JellyfinClient.id(fixture.getString("userId"))),"Wrong active account");check(plexBefore.equals(new PlexClient(c).prefs.getAll()),"Linking modified Plex");
            // Source choice must not unlink either provider, including an existing Plex installation.
            SharedPreferences plexPrefs=new PlexClient(c).prefs;plexPrefs.edit().putString("serverToken","demo").putString("serverName","Plex demo").commit();
            SettingsActivity selector=(SettingsActivity)startActivitySync(new Intent(c,SettingsActivity.class).putExtra("page",21).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));opened.add(selector);Object options=field(selector,"view");List<View> choices=(List<View>)field(options,"rows");press(choices.get(0));check(!new LibraryClient(c).isJellyfin()&&client.connected(),"Selecting Plex unlinked Jellyfin");choices=(List<View>)field(options,"rows");press(choices.get(1));check(new LibraryClient(c).isJellyfin()&&new PlexClient(c).connected(),"Selecting Jellyfin unlinked Plex");ui(()->selector.finish());restore(plexPrefs,plexBefore);
            // Password fallback must leave an existing session intact on failure and never save a password.
            press(controls(link).get(1));setText((EditText)field(link,"address"),fixture.getString("base"));press(controls(link).get(1));await(()->(Integer)field(link,"page")==1&&!((TextView)field(link,"code")).getText().toString().isEmpty(),"Second code missing");press(controls(link).get(0));check((Integer)field(link,"page")==2,"Password alternative not reachable");String beforeToken=client.prefs.getString("token","");setText((EditText)field(link,"username"),fixture.getString("username"));setText((EditText)field(link,"password"),"intentionally-invalid-fixture-password");press(controls(link).get(2));await(()->!(Boolean)field(link,"busy"),"Failed login did not complete");check(client.prefs.getString("token","").equals(beforeToken)&&((EditText)field(link,"password")).getText().length()==0,"Failed login replaced session or retained password");
            setText((EditText)field(link,"password"),fixture.getString("password"));press(controls(link).get(2));await(()->(Integer)field(link,"page")==3,"Password fallback failed");check(!client.prefs.getAll().containsValue(fixture.getString("password")),"Password persisted");
            List<PlexClient.Section> sections=client.sections();PlexClient.Section movies=null,series=null;for(PlexClient.Section section:sections){if(section.type.equals("movie"))movies=section;if(section.type.equals("show"))series=section;}check(movies!=null&&series!=null,"Movie/series libraries missing");PlexClient.LibraryPage first=client.page(movies,0),last=client.page(movies,24);check(first.received==24&&first.hasNext()&&last.received==6&&!last.hasNext(),"Real 24/6 pagination failed");Set<String> ids=new HashSet<>();for(PlexClient.Film f:first.films)ids.add(f.key);for(PlexClient.Film f:last.films)check(ids.add(f.key),"Duplicate across pages");check(client.page(series,0).films.size()>0,"Series page empty");
            List<PlexClient.Film> library=client.library();int resumes=0,latest=0;PlexClient.Film resume=null;for(PlexClient.Film film:library){if(film.continuing){resumes++;if(!film.nextEpisode)resume=film;}if(film.recentlyAdded)latest++;}check(resumes>0&&resumes<=12&&latest>0&&latest<=12,"Real feed row limits/data failed");check(resume!=null&&resume.remainingMs()>0&&resume.positionMs>0,"Real playback offset not retained");check(client.cached().size()==library.size(),"Jellyfin cache not restored");PlexClient.Film imageFilm=first.films.get(0);byte[] poster=client.image(imageFilm.thumb,168,252,false);Bitmap image=BitmapFactory.decodeByteArray(poster,0,poster.length);check(image!=null,"Authenticated poster did not decode");image.recycle();
            LibraryClient active=new LibraryClient(c);Intent item=active.open(imageFilm);check(item!=null&&item.resolveActivity(c.getPackageManager())!=null&&item.getStringExtra("ItemId").equals(JellyfinClient.guid(imageFilm.key)),"Official Android TV app item route unavailable");check(item.getExtras().size()==2,"Private session data passed to the playback app");
            List<PlexClient.Film> shared=Collections.singletonList(resume);check(ContinueWatching.merge(Collections.emptyList(),shared,JellyfinClient.PACKAGE).isEmpty(),"Jellyfin Watch Next duplicated the linked library");
            ui(()->link.finish());HomeActivity homeActivity=open(HomeActivity.class);CinemaHomeView home=(CinemaHomeView)field(homeActivity,"home");await(()->((List<?>)field(home,"cards")).size()>0,"Jellyfin home cards missing");check(Visuals.cacheKb(c)==cache,"Jellyfin increased the image cache budget");
            final Intent[] launched={null};ActivityMonitor monitor=new ActivityMonitor(){@Override public ActivityResult onStartActivity(Intent next){if(next.getComponent()!=null&&JellyfinClient.PACKAGE.equals(next.getComponent().getPackageName())){launched[0]=next;return new ActivityResult(Activity.RESULT_CANCELED,null);}return null;}};addMonitor(monitor);
            try{press((View)field(home,"play"));check(launched[0]!=null&&!JellyfinClient.id(launched[0].getStringExtra("ItemId")).isEmpty(),"Actual home action lost the Jellyfin item ID");}finally{removeMonitor(monitor);}
            capture("inicio");
            List<PlexClient.Film> entries=(List<PlexClient.Film>)field(home,"posterFilms");PlexClient.Film episode=null;int slot=-1;for(int i=0;i<entries.size();i++)if(entries.get(i).continuing&&entries.get(i).type.equals("episode")&&!entries.get(i).nextEpisode){episode=entries.get(i);slot=i;break;}check(episode!=null,"Fixture needs a started episode");String watchedEpisode=episode.key,watchedSeries=episode.seriesKey;View tile=((List<View>)field(home,"cards")).get(slot);ui(()->tile.requestFocus());long down=SystemClock.uptimeMillis();sendKeySync(new KeyEvent(down,down,KeyEvent.ACTION_DOWN,KeyEvent.KEYCODE_DPAD_CENTER,0));Thread.sleep(ViewConfiguration.getLongPressTimeout()+200);waitForIdleSync();check(((View)field(home,"overlay")).getVisibility()==View.VISIBLE,"Held OK did not open Jellyfin actions");sendKeySync(new KeyEvent(down,SystemClock.uptimeMillis(),KeyEvent.ACTION_DOWN,KeyEvent.KEYCODE_DPAD_CENTER,1));sendKeySync(new KeyEvent(down,SystemClock.uptimeMillis(),KeyEvent.ACTION_UP,KeyEvent.KEYCODE_DPAD_CENTER,0));waitForIdleSync();check(!(Boolean)field(home,"watchedBusy"),"Long-press release marked an episode");capture("marcar-visto");
            sendKeyDownUpSync(KeyEvent.KEYCODE_DPAD_CENTER);waitForIdleSync();await(()->!(Boolean)field(home,"watchedBusy")&&((View)field(home,"overlay")).getVisibility()!=View.VISIBLE,"Jellyfin watched action did not finish");List<PlexClient.Film> after=client.library();boolean nextFound=false,oldFound=false;for(PlexClient.Film f:after){if(f.continuing&&f.key.equals(watchedEpisode))oldFound=true;if(f.nextEpisode&&f.seriesKey.equals(watchedSeries)&&!f.key.equals(watchedEpisode)){nextFound=true;check(f.positionMs==0&&f.remainingMs()==f.durationMs,"Pending episode fabricated progress");}}check(!oldFound&&nextFound,"Server did not advance to the next unwatched episode");List<PlexClient.Film> onScreen=(List<PlexClient.Film>)field(home,"posterFilms");for(int i=0;i<onScreen.size();i++)if(onScreen.get(i).nextEpisode&&onScreen.get(i).seriesKey.equals(watchedSeries)){View nextTile=((List<View>)field(home,"cards")).get(i);ui(()->nextTile.requestFocus());break;}Thread.sleep(2600);capture("siguiente-episodio");
            Method change=home.getClass().getDeclaredMethod("changeFilter",int.class);change.setAccessible(true);ui(()->{try{change.invoke(home,1);}catch(Exception e){throw new RuntimeException(e);}});await(()->field(home,"catalogPage")!=null&&!((Boolean)field(home,"catalogLoading")),"Native paged catalog did not load");check(((PlexClient.LibraryPage)field(home,"catalogPage")).received==24,"Native catalog did not show bounded first page");capture("biblioteca");
            List<View> cards=(List<View>)field(home,"cards");ui(()->cards.get(cards.size()-1).requestFocus());sendKeyDownUpSync(KeyEvent.KEYCODE_DPAD_RIGHT);waitForIdleSync();await(()->field(home,"catalogPage")!=null&&((PlexClient.LibraryPage)field(home,"catalogPage")).offset==24,"Remote did not advance the real library page");
            check(plexBefore.equals(new PlexClient(c).prefs.getAll())&&Arrays.equals(apps,SidebarApps.slots(c)),"Jellyfin browsing modified Plex or shortcuts");
            ui(()->homeActivity.finish());AmbientPrefs.get(c).edit().putString("style","plex").putBoolean("weather",false).commit();SettingsActivity settings=open(SettingsActivity.class);ui(()->settings.showPreview());AmbientView ambient=(AmbientView)field(settings,"preview");await(()->((ImageView)field(ambient,"photoA")).getDrawable()!=null||((ImageView)field(ambient,"photoB")).getDrawable()!=null,"Library screensaver did not load real Jellyfin artwork");sendKeyDownUpSync(KeyEvent.KEYCODE_BACK);waitForIdleSync();ui(()->settings.finish());
            JellyfinLinkActivity manage=open(JellyfinLinkActivity.class);capture("cuenta");press(controls(manage).get(2));check((Integer)field(manage,"page")==4,"Unlink confirmation missing");press(controls(manage).get(1));check(client.connected(),"Cancel unlinked account");press(controls(manage).get(2));press(controls(manage).get(0));await(()->!client.connected(),"Unlink did not remove the Jellyfin session");check(plexBefore.equals(new PlexClient(c).prefs.getAll()),"Unlink changed Plex");
            result.putString("result","PASS real Jellyfin Quick Connect + remote UI, password fallback/failed login isolation, private credentials, exact progress, original authenticated images, 24/6 paging and remote next-page navigation, bounded resume/latest/Next Up, real server watched action and next-episode advancement, held OK guard, disk metadata, actual home playback action and official app item routing, source selection, Jellyfin screensaver artwork, duplicate suppression and independent unlink. Plex, shortcuts and the existing image budget preserved.");
        }catch(Throwable e){result.putString("error",android.util.Log.getStackTraceString(e));try{capture("failure");}catch(Exception ignored){}}
        finally{for(int i=opened.size()-1;i>=0;i--){Activity a=opened.get(i);ui(()->{if(!a.isFinishing())a.finish();});}for(Map.Entry<SharedPreferences,Map<String,?>> entry:saved.entrySet())restore(entry.getKey(),entry.getValue());fixtureFile.delete();}
        finish(result.containsKey("error")?1:-1,result);
    }
}
